mapper.insert:
INSERT INTO evaluations_51 (
    mapping_id, element_id, score1, score2, self_score, reason1, reason2,
    confirm_status_code, is_deleted, version,
    created_at, created_by, updated_at, updated_by
) VALUES (
    #{mappingId}, #{elementId}, #{score1}, #{score2}, #{selfScore}, #{reason1}, #{reason2},
    #{confirmStatusCode}, #{isDeleted}, #{version},
    #{createdAt}, #{createdBy}, #{updatedAt}, #{updatedBy}
)

mapper.select:
SELECT *
FROM evaluations_51
WHERE mapping_id = #{mappingId}
  AND element_id = #{elementId}
  AND is_deleted = 'n'

mapper.update:
UPDATE evaluations_51
score1 = #{score1}, score2 = #{score2}, self_score = #{selfScore}, reason1 = #{reason1}, reason2 = #{reason2}, confirm_status_code = #{confirmStatusCode}, updated_at = #{updatedAt}, updated_by = #{updatedBy}, version = version + 1
WHERE eval_id = #{evalId} AND version = #{version}

mapper.delete:
DELETE FROM evaluations_51
WHERE mapping_id IN (
    SELECT mapping_id 
    FROM evaluator_mappings_51 
    WHERE period_id = #{periodId}
)
